import React, { useState } from 'react';
import {
  Box,
  Paper,
  Typography,
  TextField,
  Button,
  Grid,
  Select,
  MenuItem,
  FormControl,
  InputLabel,
  Container,
  Alert,
  Snackbar
} from '@mui/material';
import axios from 'axios';

function CostCalculator() {
  const [formData, setFormData] = useState({
    deployment: {
      size: 'Small',
      data_throughput: 100,
      peak_load: 10
    },
    consumer: {
      pattern: 'Publish-Subscribe',
      num_consumers: 100,
      data_distribution_volume: 50,
      request_count: 1000,
      concurrent_users: 10
    },
    infrastructure: {
      environment: 'dev',
      region: 'us-east-1',
      compute_resources: {
        instances: 2,
        cpu_cores: 4,
        memory_gb: 16
      },
      storage_requirements: {
        persistent_gb: 100,
        backup_gb: 200
      },
      additional_services: ['monitoring', 'logging']
    },
    cloud_provider: 'aws'
  });

  const [costBreakdown, setCostBreakdown] = useState(null);
  const [notification, setNotification] = useState({
    open: false,
    message: '',
    severity: 'success'
  });

  const handleInputChange = (category, field, value) => {
    setFormData(prev => ({
      ...prev,
      [category]: {
        ...prev[category],
        [field]: value
      }
    }));
  };

  const handleNestedInputChange = (category, parent, field, value) => {
    setFormData(prev => ({
      ...prev,
      [category]: {
        ...prev[category],
        [parent]: {
          ...prev[category][parent],
          [field]: value
        }
      }
    }));
  };

  const calculateCosts = async () => {
    try {
      const response = await axios.post('http://localhost:8000/calculate-cost', formData);
      setCostBreakdown(response.data);
      setNotification({
        open: true,
        message: 'Cost calculation successful!',
        severity: 'success'
      });
    } catch (error) {
      setNotification({
        open: true,
        message: 'Error calculating costs: ' + (error.response?.data?.detail || error.message),
        severity: 'error'
      });
    }
  };

  const handleCloseNotification = () => {
    setNotification({ ...notification, open: false });
  };

  return (
    <Container maxWidth="lg">
      <Paper elevation={3} sx={{ p: 3, mt: 3 }}>
        <Typography variant="h4" gutterBottom>
          Cloud Infrastructure Cost Calculator
        </Typography>

        {/* Deployment Configuration */}
        <Box sx={{ mb: 4 }}>
          <Typography variant="h6" gutterBottom>
            Deployment Configuration
          </Typography>
          <Grid container spacing={3}>
            <Grid item xs={12} md={4}>
              <FormControl fullWidth>
                <InputLabel>Deployment Size</InputLabel>
                <Select
                  value={formData.deployment.size}
                  label="Deployment Size"
                  onChange={(e) => handleInputChange('deployment', 'size', e.target.value)}
                >
                  <MenuItem value="Small">Small</MenuItem>
                  <MenuItem value="Medium">Medium</MenuItem>
                  <MenuItem value="Large">Large</MenuItem>
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} md={4}>
              <TextField
                fullWidth
                label="Data Throughput (GB/month)"
                type="number"
                value={formData.deployment.data_throughput}
                onChange={(e) => handleInputChange('deployment', 'data_throughput', parseFloat(e.target.value))}
              />
            </Grid>
            <Grid item xs={12} md={4}>
              <TextField
                fullWidth
                label="Peak Load (GB/hour)"
                type="number"
                value={formData.deployment.peak_load}
                onChange={(e) => handleInputChange('deployment', 'peak_load', parseFloat(e.target.value))}
              />
            </Grid>
          </Grid>
        </Box>

        {/* Consumer Configuration */}
        <Box sx={{ mb: 4 }}>
          <Typography variant="h6" gutterBottom>
            Consumer Configuration
          </Typography>
          <Grid container spacing={3}>
            <Grid item xs={12} md={4}>
              <FormControl fullWidth>
                <InputLabel>Pattern</InputLabel>
                <Select
                  value={formData.consumer.pattern}
                  label="Pattern"
                  onChange={(e) => handleInputChange('consumer', 'pattern', e.target.value)}
                >
                  <MenuItem value="Publish-Subscribe">Publish-Subscribe</MenuItem>
                  <MenuItem value="Request-Response">Request-Response</MenuItem>
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} md={4}>
              <TextField
                fullWidth
                label="Number of Consumers"
                type="number"
                value={formData.consumer.num_consumers}
                onChange={(e) => handleInputChange('consumer', 'num_consumers', parseInt(e.target.value))}
              />
            </Grid>
            <Grid item xs={12} md={4}>
              <TextField
                fullWidth
                label="Data Distribution Volume (GB/month)"
                type="number"
                value={formData.consumer.data_distribution_volume}
                onChange={(e) => handleInputChange('consumer', 'data_distribution_volume', parseFloat(e.target.value))}
              />
            </Grid>
          </Grid>
        </Box>

        {/* Infrastructure Configuration */}
        <Box sx={{ mb: 4 }}>
          <Typography variant="h6" gutterBottom>
            Infrastructure Configuration
          </Typography>
          <Grid container spacing={3}>
            <Grid item xs={12} md={4}>
              <FormControl fullWidth>
                <InputLabel>Cloud Provider</InputLabel>
                <Select
                  value={formData.cloud_provider}
                  label="Cloud Provider"
                  onChange={(e) => handleInputChange('cloud_provider', '', e.target.value)}
                >
                  <MenuItem value="aws">AWS</MenuItem>
                  <MenuItem value="azure">Azure</MenuItem>
                  <MenuItem value="gcp">GCP</MenuItem>
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} md={4}>
              <FormControl fullWidth>
                <InputLabel>Environment</InputLabel>
                <Select
                  value={formData.infrastructure.environment}
                  label="Environment"
                  onChange={(e) => handleInputChange('infrastructure', 'environment', e.target.value)}
                >
                  <MenuItem value="dev">Development</MenuItem>
                  <MenuItem value="staging">Staging</MenuItem>
                  <MenuItem value="prod">Production</MenuItem>
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} md={4}>
              <FormControl fullWidth>
                <InputLabel>Region</InputLabel>
                <Select
                  value={formData.infrastructure.region}
                  label="Region"
                  onChange={(e) => handleInputChange('infrastructure', 'region', e.target.value)}
                >
                  <MenuItem value="us-east-1">US East (N. Virginia)</MenuItem>
                  <MenuItem value="us-west-2">US West (Oregon)</MenuItem>
                  <MenuItem value="eu-west-1">EU (Ireland)</MenuItem>
                </Select>
              </FormControl>
            </Grid>
          </Grid>
        </Box>

        <Button
          variant="contained"
          color="primary"
          size="large"
          onClick={calculateCosts}
          sx={{ mt: 2 }}
        >
          Calculate Costs
        </Button>

        {/* Cost Breakdown Display */}
        {costBreakdown && (
          <Box sx={{ mt: 4 }}>
            <Typography variant="h5" gutterBottom>Cost Breakdown</Typography>
            <Grid container spacing={3}>
              <Grid item xs={12} md={3}>
                <Paper elevation={2} sx={{ p: 2 }}>
                  <Typography variant="subtitle1">Network Cost</Typography>
                  <Typography variant="h6">${costBreakdown.network_cost.toFixed(2)}</Typography>
                </Paper>
              </Grid>
              <Grid item xs={12} md={3}>
                <Paper elevation={2} sx={{ p: 2 }}>
                  <Typography variant="subtitle1">Consumer Cost</Typography>
                  <Typography variant="h6">${costBreakdown.consumer_cost.toFixed(2)}</Typography>
                </Paper>
              </Grid>
              <Grid item xs={12} md={3}>
                <Paper elevation={2} sx={{ p: 2 }}>
                  <Typography variant="subtitle1">Infrastructure Cost</Typography>
                  <Typography variant="h6">${costBreakdown.infrastructure_cost.toFixed(2)}</Typography>
                </Paper>
              </Grid>
              <Grid item xs={12} md={3}>
                <Paper elevation={2} sx={{ p: 2 }}>
                  <Typography variant="subtitle1">Total Cost</Typography>
                  <Typography variant="h6" color="primary">${costBreakdown.total_cost.toFixed(2)}</Typography>
                </Paper>
              </Grid>
            </Grid>
          </Box>
        )}

        <Snackbar
          open={notification.open}
          autoHideDuration={6000}
          onClose={handleCloseNotification}
        >
          <Alert onClose={handleCloseNotification} severity={notification.severity}>
            {notification.message}
          </Alert>
        </Snackbar>
      </Paper>
    </Container>
  );
}

export default CostCalculator;
